body:
tile-r2 released src/tile.rs, which you are watching. What changed while they held it:

diff --git a/src/tile.rs b/src/tile.rs
index 1501227..cccdbf9 100644
--- a/src/tile.rs
+++ b/src/tile.rs
@@ -16,6 +16,16 @@
 //! release of this crate has ever shipped, under either name, so there is no
 //! consumer for the old shape to break out from under. See
 //! `docs/tile-contract.md`'s "Changing the contract" section.
+//!
+//! **Not the CLI**, deliberately: [`build`] takes an already-resolved list of
+//! repo roots rather than reading `~/.config/quivive/repos` itself or knowing
+//! about `clap::Args`. Resolving "no `--repo`" to the registry (S1-S2),
+//! choosing JSON vs the one-line [`Payload::text`] form, and mapping
+//! `--exit-on` through [`severity`] are `src/main.rs`'s job, the same way they
+//! were for the single-repo tile this replaces — see its `tick_once`. That
+//! keeps this file testable as a pure function of (repo roots, clock,
+//! thresholds) with no `crate::cli::Common` in its signature to go stale
+//! against.

 use std::collections::BTreeMap;
 use std::path::{Path, PathBuf};
@@ -24,13 +34,11 @@ use anyhow::Result;
 use chrono::{DateTime, SecondsFormat, Utc};
 use serde::Serialize;

-use crate::cli::Common;
 use crate::reader::{self, Readings, plan, sidecar};
 use crate::state::{
     self, AttentionItem, GateSnapshot, LeaseSnapshot, PlanSnapshot, RepoSnapshot, RepoStatus,
     State, Thresholds, WaveSnapshot,
 };
-use crate::{EXIT_OK, EXIT_TRIGGERED, dur, registry};

 /// Contract version. See the module docs and `docs/tile-contract.md`.
 pub const TILE_V: u32 = 1;
@@ -96,7 +104,12 @@ pub struct Payload {
 /// it lives here rather than as a derived `Ord` on the type itself so that
 /// state.rs stays free of a concern (severity, across repos) it has never
 /// needed before this file existed.
-fn severity(status: RepoStatus) -> u8 {
+///
+/// `pub`: `src/main.rs` needs this same ordering to implement `--exit-on`
+/// (compare the payload's overall `status` against the threshold the CLI was
+/// given), and a second copy of this ordering is exactly the drift this
+/// function exists to prevent.
+pub fn severity(status: RepoStatus) -> u8 {
     match status {
         RepoStatus::HumanNeeded => 4,
         RepoStatus::Active => 3,
@@ -162,7 +175,9 @@ fn forget_sweep(
 fn needs_decision_ids(rows: &[sidecar::Row]) -> Vec<String> {
     let mut ids: Vec<String> = rows
         .iter()
-        .filter(|r| r.field.as_deref() == Some("type") && r.new_value.as_deref() == Some("needs-decision"))
+        .filter(|r| {
+            r.field.as_deref() == Some("type") && r.new_value.as_deref() == Some("needs-decision")
+        })
         .map(|r| r.issue_id.clone())
         .collect();
     ids.sort();
@@ -424,66 +439,3 @@ fn status_str(status: RepoStatus) -> String {
         .and_then(|v| v.as_str().map(str::to_string))
         .unwrap_or_else(|| "unknown".to_string())
 }
-
-/// `quivive tile`'s whole one-shot path (S10): resolve which repos to read
-/// (the registry, S1-S2, unless `--repo` names one explicitly), build the
-/// payload with one clock read, print it, and decide the exit code.
-///
-/// `--repo` bypasses the registry entirely rather than requiring a one-line
-/// registry file first: a bar instance already pointed at a single repository
-/// (a per-project waybar config, a CI job) has no reason to hand-maintain
-/// `~/.config/quivive/repos` just to ask about the one repo it already knows.
-pub fn run(common: &Common) -> Result<i32> {
-    let thresholds = Thresholds {
-        active: dur::parse(&common.active_window)?,
-        idle: dur::parse(&common.idle_window)?,
-        dead: dur::parse(&common.dead_window)?,
-        forget: dur::parse(&common.forget)?,
-    };
-    thresholds.validate()?;
-
-    let (repo_roots, degrade_unreadable) = match &common.repo {
-        Some(p) => (vec![p.clone()], false),
-        None => (registry::read()?, true),
-    };
-
-    // One read of the clock for the whole payload, however many repos it
-    // covers — three reads in three places is a tick that cannot be golden,
-    // and a payload whose `at` disagrees with what each repo was judged
-    // against.
-    let now = crate::now()?;
-    let payload = build(
-        &repo_roots,
-        now,
-        &thresholds,
-        !common.no_cursor,
-        degrade_unreadable,
-    )?;
-
-    print(&payload, common.text)?;
-
-    if let Some(threshold) = common.exit_on
-        && severity(payload.status) >= severity(threshold)
-    {
-        return Ok(EXIT_TRIGGERED);
-    }
-    Ok(EXIT_OK)
-}
-
-fn print(payload: &Payload, text: bool) -> Result<()> {
-    use std::io::Write;
-    let mut out = std::io::stdout().lock();
-    if text {
-        writeln!(out, "{}", payload.text())?;
-    } else {
-        // Pretty, and deliberately: a tile is read by people at least as often
-        // as by bars, `jq` does not care, and a diff of two pretty payloads is
-        // legible where a diff of one long line is not — which the goldens
-        // depend on.
-        writeln!(out, "{}", serde_json::to_string_pretty(payload)?)?;
-    }
-    // Flush explicitly: `quivive tile --stream | head -1` closes the pipe, and
-    // an ignored flush error there is a broken-pipe panic on exit.
-    let _ = out.flush();
-    Ok(())
-}

Holder's HEAD at release: 70b9ec8

This is a contract notice, not a code delivery: tile-r2 wrote this on branch agent/tile, in their own worktree. It cannot appear in your tree until agent/tile merges and you merge that. Read the diff for what the contract now says and carry on — the file will not change under you, so there is nothing to wait for.

Questions, or a contract you need changed back? Reply to tile-r2 in THIS thread — `pact msg inbox` shows its id, then `pact msg send --to tile-r2 --thread <id> "..."`. A reply without `--thread` starts a new conversation nobody can follow back to this diff.

You are receiving this because you ran `pact watch add`. `pact watch rm src/tile.rs` stops it.
